var defaultQuestions = (grade, chapter, sectionIndex) => DEFAULT_QUESTIONS[`${grade}-${chapter}`]?.[sectionIndex] ?? [];
var resolveQuestions = (saved, fallback) => {
  const clean = (saved ?? []).map((q) => q.trim()).filter(Boolean);
  return clean.length ? clean : fallback;
};
var summarize = (questions, responses) => questions.map((question) => {
  const counts = [0, 0, 0];
  for (const r of responses) {
    const i = r.questions.indexOf(question);
    const v = i >= 0 ? r.ratings[i] : void 0;
    if (isScaleValue(v)) counts[v - 1]++;
  }
  return { question, counts, answered: counts.reduce((a, b) => a + b, 0) };
});

// src/lib/mcp/tools/self-assessment-summary.ts
var self_assessment_summary_default = defineTool5({
  name: "self_assessment_summary",
  title: "Sammanfatta sj\xE4lvskattning",
  description: "Summarize self-assessment answers per question for one sub-chapter. Teachers see the class; students see only their own answers.",
  inputSchema: {
    grade: gradeSchema,
    chapter: chapterSchema,
    sectionIndex: z4.number().int().min(0).max(30).describe("Sub-chapter index (0 = first), see list_chapter_sections.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ grade, chapter, sectionIndex }, ctx) => {
    if (!ctx.isAuthenticated()) return fail("Not authenticated");
    const db = supabaseForUser(ctx);
    const [q, r] = await Promise.all([
      db.from("self_assessment_questions").select("questions").eq("grade", grade).eq("chapter", chapter).eq("section_index", sectionIndex).maybeSingle(),
      db.from("self_assessment_responses").select("questions, ratings").eq("grade", grade).eq("chapter", chapter).eq("section_index", sectionIndex).limit(500)
    ]);
    if (q.error) return fail(q.error.message);
    if (r.error) return fail(r.error.message);
    const questions = resolveQuestions(q.data?.questions, defaultQuestions(grade, chapter, sectionIndex));
    const summary = summarize(questions, (r.data ?? []).map((x) => ({ questions: x.questions, ratings: x.ratings })));
    const rows = summary.map((s) => ({
      question: s.question,
      answered: s.answered,
      counts: SCALE.map((l, i) => ({ label: l.label, count: s.counts[i] }))
    }));
    const text = rows.length ? `${r.data?.length ?? 0} svar
` + rows.map((s) => `${s.question}
  ${s.counts.map((c) => `${c.label}: ${c.count}`).join(" \xB7 ")}`).join("\n") : "Inga fr\xE5gor f\xF6r delkapitlet.";
    return { content: [{ type: "text", text }], structuredContent: { responses: r.data?.length ?? 0, questions: rows } };
  }
});

